/* Fast entry: keyboard-first forms, account-scoped suggestions, and repeat saves. */
window.FareEntry={create(deps){
  'use strict';
  const {B,esc,icon,field,selectField,accountOptions,vatOptions,modal,detailModal,change,getProfile:p,getYear:y,defaultDate,categoryName,pounds,plain,btn}=deps;
  const node=s=>document.querySelector(s);
  const value=(form,name)=>form.elements.namedItem(name)?.value||'';
  const defaults=kind=>p().entryDefaults?.[kind]||{};
  const entryDate=d=>d&&d>=y().start&&d<=y().end?d:defaultDate();
  const moneyAccount=id=>B.account(p(),id)?.kind?id:p().accounts.find(a=>a.kind==='bank')?.id||'cash';
  const readableDate=d=>{const iso=B.date(d);return `${iso.slice(8,10)}/${iso.slice(5,7)}/${iso.slice(0,4)}`;};
  function dateField(label,d){return field(label,'date','text',readableDate(d),'required inputmode="numeric" maxlength="10" autocomplete="off" placeholder="DD/MM/YYYY or DDMMYY"');}
  function wireDate(form){const input=form.elements.date;function normalise(){try{input.value=readableDate(input.value);input.setCustomValidity('');}catch(error){input.setCustomValidity(error.message);}}input.addEventListener('input',()=>input.setCustomValidity(''));input.addEventListener('blur',normalise);input.addEventListener('change',normalise);input.addEventListener('keydown',e=>{if(e.key==='Tab')normalise();});return normalise;}
  function categoryField(id){const a=B.account(p(),id),parent=a?.parent?B.account(p(),a.parent):a,children=parent?p().accounts.filter(c=>c.parent===parent.id):[];const childName=a?.parent?a.name:children.length?(a?.id==='payables'?'General supplier balance':a?.id==='expenses'?'General expenses':''):'';
    return `<div class="full category-pair"><label class="field category-group-field">Category<input name="categoryGroup" value="${esc(parent?.name||'')}" required role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="Expenses, Suppliers, Capital…"></label><label class="field combo-field">Subcategory<input name="categorySearch" value="${esc(childName)}" role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="Fuel, Car wash…" ${children.length?'required':'disabled'}></label><button type="button" class="button small new-subcategory-button" data-entry-new-subcategory tabindex="-1" aria-keyshortcuts="Alt+N" title="New subcategory (Alt+N)">${icon('plus')}New subcategory</button><input name="categoryId" type="hidden" value="${esc(id||'')}"><div class="new-subcategory-editor full" hidden><label class="field">New subcategory name<input name="newSubcategoryName" maxlength="100" autocomplete="off"></label><label class="field" data-linked-expense hidden>Expense category for its receipts<select name="newSubcategoryExpense"><option value="">Create a matching expense category</option>${p().accounts.filter(c=>c.type==='expense').map(c=>`<option value="${esc(c.id)}">${esc(categoryName(c.id))}</option>`).join('')}</select></label><div class="actions">${'<button type="button" class="button small primary" data-create-subcategory>Create & select</button><button type="button" class="button small" data-cancel-subcategory>Cancel</button>'}</div><p class="hint">Alt+N opens this editor without losing the entry.</p></div></div>`;
  }
  function combo(input,getOptions,onSelect,onInput=()=>{}){
    const box=document.createElement('div');box.className='suggestions';box.id='suggestions-'+B.uid();box.setAttribute('role','listbox');box.hidden=true;input.parentElement.append(box);input.setAttribute('aria-controls',box.id);
    let options=[],active=0;
    function close(){box.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
    function paint(){box.innerHTML=options.map((opt,i)=>`<button type="button" role="option" id="${box.id}-${i}" aria-selected="${i===active}" class="suggestion ${i===active?'active':''}" data-option="${i}"><span>${esc(opt.label)}</span>${opt.detail?`<small>${esc(opt.detail)}</small>`:''}</button>`).join('');box.hidden=!options.length;box.classList.toggle('above',input.getBoundingClientRect().bottom+Math.min(options.length*44,215)>node('#modal').getBoundingClientRect().bottom-20);input.setAttribute('aria-expanded',String(!!options.length));if(options.length)input.setAttribute('aria-activedescendant',`${box.id}-${active}`);}
    function open(){options=getOptions(input.value).slice(0,8);active=0;paint();}
    function choose(i){const opt=options[i];if(!opt)return;input.value=opt.label;onSelect(opt);close();}
    input.addEventListener('input',()=>{onInput(input.value);open();});input.addEventListener('focus',open);
    input.addEventListener('blur',()=>{onInput(input.value);setTimeout(close,100);});
    input.addEventListener('keydown',e=>{
      if(e.key==='Escape'&&!box.hidden){e.preventDefault();e.stopPropagation();close();return;}
      if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(box.hidden)open();else if(options.length){active=(active+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;paint();}return;}
      if((e.key==='Enter'||e.key==='Tab')&&!box.hidden&&options.length){if(e.key==='Enter')e.preventDefault();choose(active);}
    });
    box.addEventListener('mousedown',e=>e.preventDefault());box.addEventListener('click',e=>{const option=e.target.closest('[data-option]');if(option){choose(Number(option.dataset.option));input.focus();close();}});
    return {close,refresh:open};
  }
  function wireCategory(form,type=null,direction=()=>value(form,'direction')||'payment'){
    const input=form.elements.categorySearch,group=form.elements.categoryGroup,hidden=form.elements.categoryId,pair=input.closest('.category-pair');
    const allowed=a=>{const t=typeof type==='function'?type():type;return !a.kind&&a.id!=='transfer'&&(!t||(t==='expense'||t==='purchase'?a.type==='expense'||B.isSupplierAccount(p(),a.id):a.type===t));};
    const groups=()=>p().accounts.filter(a=>!a.parent&&allowed(a));
    const selectedGroup=()=>groups().find(a=>a.name.toLowerCase()===group.value.trim().toLowerCase());
    function leaves(){const parent=selectedGroup();if(!parent)return [];const list=B.categorySuggestions(p(),value(form,'accountId'),direction()).filter(a=>a.parent===parent.id&&allowed(a));const t=typeof type==='function'?type():type;
      if(parent.id==='expenses')list.push({...parent,name:'General expenses'});
      if(parent.id==='payables'&&!t)list.push({...parent,name:'General supplier balance'});return list;}
    function updateRequired(){const parent=selectedGroup(),children=leaves();input.disabled=!parent||!children.length;input.required=children.length>0;input.placeholder=children.length?'Fuel, Car wash…':'No subcategory';}
    function sync(){const parent=selectedGroup();if(!parent){hidden.value='';return;}const children=leaves();hidden.value=children.length?children.find(a=>a.name.toLowerCase()===input.value.trim().toLowerCase())?.id||'':parent.id;updateRequired();}
    function set(id){const a=B.account(p(),id),parent=a?.parent?B.account(p(),a.parent):a;group.value=parent?.name||'';input.value=a?.parent?a.name:a?.id==='payables'?'General supplier balance':a?.id==='expenses'?'General expenses':'';hidden.value=id||'';updateRequired();rootWidget.close();leafWidget.close();}
    function chooseGroup(opt){const oldLeaf=input.value;group.value=opt.label;const matching=leaves().find(a=>a.name.toLowerCase()===oldLeaf.toLowerCase());if(matching)input.value=matching.name;else if(opt.id==='capital-group')input.value=direction()==='receipt'?'Capital introduced':'Drawings';else input.value='';sync();input.dispatchEvent(new Event('categorychosen'));}
    const rootWidget=combo(group,text=>groups().filter(a=>a.name.toLowerCase().startsWith(text.trim().toLowerCase())).map(a=>({id:a.id,label:a.name,detail:B.isSupplierAccount(p(),a.id)?'Payments to settle with receipts':a.type==='expense'?'Direct expenses · no invoice required':a.id==='capital-group'?'Capital movements · no invoice required':a.type})),chooseGroup,()=>{updateRequired();sync();});
    const leafWidget=combo(input,text=>leaves().filter(a=>a.name.toLowerCase().startsWith(text.trim().toLowerCase())).map(a=>({id:a.id,label:a.name,detail:categoryName(a.id)})),opt=>{hidden.value=opt.id;input.dispatchEvent(new Event('categorychosen'));},sync);
    hidden.addEventListener('change',()=>{set(hidden.value);input.dispatchEvent(new Event('categorychosen'));});group.addEventListener('input',()=>input.dispatchEvent(new Event('categorychosen')));
    const editor=pair.querySelector('.new-subcategory-editor'),newName=form.elements.newSubcategoryName,trigger=pair.querySelector('[data-entry-new-subcategory]');
    function openEditor(){const parent=selectedGroup();if(!parent){deps.toast('Choose a category first.',true);group.focus();return;}editor.hidden=false;pair.querySelector('[data-linked-expense]').hidden=!B.isSupplierAccount(p(),parent.id);newName.focus();}
    trigger.addEventListener('click',openEditor);pair.querySelector('[data-cancel-subcategory]').addEventListener('click',()=>{editor.hidden=true;input.focus();});
    pair.querySelector('[data-create-subcategory]').addEventListener('click',async()=>{const button=pair.querySelector('[data-create-subcategory]');button.disabled=true;try{const parent=selectedGroup();if(!parent)throw new Error('Choose a category first.');let child;await change(()=>{child=B.addSubcategory(p(),parent.id,newName.value,{expenseCategoryId:value(form,'newSubcategoryExpense')||undefined});},'Subcategory created',false);set(child.id);input.dispatchEvent(new Event('categorychosen'));editor.hidden=true;newName.value='';input.focus();}catch(e){deps.toast(e.message,true);}finally{button.disabled=false;}});
    editor.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();e.stopPropagation();pair.querySelector('[data-create-subcategory]').click();}});
    form.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();openEditor();}});
    set(hidden.value);return {set,sync,disabled(disabled){group.disabled=disabled;input.disabled=disabled||!leaves().length;trigger.disabled=disabled;hidden.disabled=disabled;}};
  }
  function keyboard(form){form.addEventListener('keydown',e=>{if(e.key==='Enter'&&((e.ctrlKey||e.metaKey)||(e.target.name==='amount'&&!e.defaultPrevented))){e.preventDefault();form.requestSubmit(form.querySelector('[data-entry-next]'));}});}
  function focusEntry(form,name){const input=form.elements.namedItem(name);input.focus();input.select();}
  function saveDefaults(kind,data){p().entryDefaults||={};p().entryDefaults[kind]=data;}
  function transaction(seed={}){
    const d={...defaults('transaction'),...seed,keepCategory:seed.categoryId?true:defaults('transaction').keepCategory},accountId=moneyAccount(d.accountId),date=entryDate(d.date),direction=d.direction||'payment';
    let saved=0,category,manualCategory=!!d.keepCategory,manualPercent=false,manualContact=false;
    modal('Quick transaction',`<div class="entry-context">${selectField('Account','accountId',accountOptions(accountId,'money'))}${selectField('Type','direction',`<option value="payment" ${direction==='payment'?'selected':''}>Payment · money out</option><option value="receipt" ${direction==='receipt'?'selected':''}>Receipt · money in</option>`)}</div><div class="form-grid">${dateField('Date',date)}${field('Details / merchant','description','text','','required maxlength="250" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false"')}${categoryField(d.keepCategory?d.categoryId:'suspense')}${field('Amount (£)','amount','number','','required min="0.01" step="0.01"',true)}<div class="entry-hint full" id="entry-memory-status" aria-live="polite">Suggestions come from this driver’s entries on the selected account.</div></div><details class="entry-options"><summary>More options</summary><div class="form-grid">${selectField('VAT code','vatCode',vatOptions(d.vatCode||'out-of-scope'))}${field('Business use (%)','businessPercent','number',100,'required min="0" max="100" step="0.01"')}${selectField('Contact (optional)','contactId',`<option value="">No contact</option>${p().contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}`)}<label class="check-label full"><input type="checkbox" name="keepCategory" ${d.keepCategory?'checked':''}>Keep this category for the next entry</label></div></details><div class="entry-shortcuts">Enter: save & next · Ctrl+Enter: save & next · Tab: move between fields</div>`, 'Save & close',async(f,form)=>{
      category.sync();const categoryId=value(form,'categoryId');
      const input={date:B.date(f.get('date')),description:String(f.get('description')).trim(),accountId:f.get('accountId'),amount:B.money(f.get('amount'))*(f.get('direction')==='payment'?-1:1),categoryId,businessPercent:Number(f.get('businessPercent')),vatCode:f.get('vatCode')||'out-of-scope',contactId:f.get('contactId')||''};
      await change(()=>{B.ensureFinancialPeriod(p(),input.date);B.addTransaction(p(),input);saveDefaults('transaction',{date:input.date,accountId:input.accountId,direction:f.get('direction'),categoryId,businessPercent:input.businessPercent,vatCode:input.vatCode,keepCategory:!!f.get('keepCategory')});},'Transaction saved',false);saved++;
    },'',{continuous:true,onNext(form){manualCategory=form.elements.keepCategory.checked;manualPercent=false;manualContact=false;form.elements.description.value='';form.elements.amount.value='';form.elements.contactId.value='';form.elements.businessPercent.value=manualCategory?(defaults('transaction').businessPercent??100):100;category.set(manualCategory?value(form,'categoryId'):'suspense');node('#entry-memory-status').textContent=`${saved} saved in this session. Ready for the next transaction.`;focusEntry(form,'description');}});
    const form=node('#modal-form');category=wireCategory(form);keyboard(form);wireDate(form);if(d.keepCategory)form.elements.businessPercent.value=d.businessPercent??100;
    function suggest(){const memory=B.findEntryMemory(p(),value(form,'accountId'),value(form,'description'),value(form,'direction'));
      if(manualCategory)return;
      if(memory){category.set(memory.categoryId);if(!manualPercent)form.elements.businessPercent.value=memory.businessPercent;if(form.elements.vatCode)form.elements.vatCode.value=memory.vatCode||'out-of-scope';if(!manualContact)form.elements.contactId.value=memory.contactId||'';node('#entry-memory-status').textContent=`Remembered: ${categoryName(memory.categoryId)} · ${memory.businessPercent}% business use.`;}
      else{if(!form.elements.keepCategory.checked)category.set('suspense');if(!manualPercent)form.elements.businessPercent.value='100';if(form.elements.vatCode)form.elements.vatCode.value=defaults('transaction').vatCode||'out-of-scope';if(!manualContact)form.elements.contactId.value='';node('#entry-memory-status').textContent='No saved match yet. Choose a category to remember it.';}
    }
    combo(form.elements.description,text=>B.entrySuggestions(p(),value(form,'accountId'),value(form,'direction'),text).map(m=>({label:m.description,detail:categoryName(m.categoryId)})),suggest,suggest);
    for(const name of ['accountId','direction'])form.elements[name].addEventListener('change',()=>{manualCategory=!!form.elements.keepCategory.checked;manualPercent=false;manualContact=false;suggest();});
    form.elements.businessPercent.addEventListener('input',()=>manualPercent=true);form.elements.contactId.addEventListener('change',()=>manualContact=true);
    form.elements.categorySearch.addEventListener('input',()=>manualCategory=true);
    form.elements.categorySearch.addEventListener('categorychosen',()=>{manualCategory=true;const a=B.account(p(),value(form,'categoryId'));node('#entry-memory-status').textContent=B.isSupplierAccount(p(),a?.id)?'Supplier payment: match a receipt/invoice to clear this balance.':a?.type==='expense'||a?.type==='equity'?'Direct expense/capital entry: no receipt or invoice is needed to settle it.':'This category will be remembered when you save.';});focusEntry(form,'description');
  }
  function receipt(seed={}){
    const d={...defaults('receipt'),...seed},accountId=moneyAccount(d.accountId);let saved=0,category,manualCategory=false,manualPercent=false;
    modal('Quick receipt',`<div class="entry-context">${selectField('Bank / cash account','accountId',accountOptions(accountId,'money'))}${selectField('Payment handling','paymentMode',`<option value="match" ${!d.paymentMode||d.paymentMode==='match'?'selected':''}>Match existing statement payment</option><option value="new" ${d.paymentMode==='new'?'selected':''}>Record a new payment</option><option value="unpaid" ${d.paymentMode==='unpaid'?'selected':''}>Unpaid supplier bill</option>`)}</div><div class="form-grid">${dateField('Receipt date',entryDate(d.date))}${field('Supplier / merchant','supplier','text','','required maxlength="100" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false"')}${categoryField(d.categoryId||'fuel','expense')}${field('Total (£)','amount','number','','required min="0.01" step="0.01"',true)}<div class="entry-hint full" id="entry-memory-status" aria-live="polite">Enter a supplier name; new suppliers are created automatically.</div><label class="field full" id="receipt-match-field" hidden>Choose the existing payment<select name="transactionId"><option value="">Leave unmatched for now</option></select></label><div id="receipt-payment-status" class="notice full" aria-live="polite"></div></div><details class="entry-options"><summary>Reference & business use (optional)</summary><div class="form-grid">${selectField('VAT code','vatCode',vatOptions(d.vatCode||'out-of-scope','purchase'))}${field('VAT amount (£)','vat','number',d.vat||'0.00','min="0" step="0.01"')}${field('Receipt reference','reference','text','','maxlength="100" placeholder="Auto-generated if blank"')}${field('Business use (%)','businessPercent','number',d.businessPercent??100,'required min="0" max="100" step="0.01"')}${field('Details (optional)','description','text','','maxlength="250"',true)}</div></details><div class="entry-shortcuts">No image upload needed · Enter / Ctrl+Enter: save & next</div>`, 'Save & close',async(f,form)=>{
      category.sync();const input={date:B.date(f.get('date')),supplier:String(f.get('supplier')).trim(),amount:B.money(f.get('amount')),categoryId:value(form,'categoryId'),accountId:f.get('accountId'),paymentMode:f.get('paymentMode'),businessPercent:Number(f.get('businessPercent')),vatCode:f.get('vatCode')||'out-of-scope',vat:B.money(f.get('vat')||'0'),reference:String(f.get('reference')).trim(),description:String(f.get('description')).trim(),transactionId:f.get('transactionId')||''};
      let result;await change(()=>{B.ensureFinancialPeriod(p(),input.date);result=B.addQuickReceipt(p(),input);saveDefaults('receipt',{date:input.date,accountId:input.accountId,categoryId:input.categoryId,businessPercent:input.businessPercent,vatCode:input.vatCode,vat:input.vat,paymentMode:input.paymentMode});},null,false);saved++;
      const message=result.status==='paid'?'Receipt saved and payment linked.':result.status==='unpaid'?'Supplier bill saved unpaid.':'Receipt saved awaiting payment matching.';
      deps.toast(message);form.dataset.lastReceiptMessage=message;
    },'',{continuous:true,onNext(form){manualCategory=false;manualPercent=false;form.elements.amount.value='';form.elements.supplier.value='';form.elements.reference.value='';form.elements.description.value='';form.elements.transactionId.innerHTML='<option value="">Leave unmatched for now</option>';node('#receipt-match-field').hidden=true;node('#entry-memory-status').textContent=`${saved} saved. ${form.dataset.lastReceiptMessage}`;paymentPreview();focusEntry(form,'date');}});
    const form=node('#modal-form');category=wireCategory(form,'expense',()=> 'payment');keyboard(form);wireDate(form);
    function paymentPreview(){const mode=value(form,'paymentMode'),status=node('#receipt-payment-status'),select=form.elements.transactionId,old=select.value;node('#receipt-match-field').hidden=true;select.innerHTML='<option value="">Leave unmatched for now</option>';
      if(mode==='new'){status.textContent='A new payment will be added to this account. Use this only if the payment is not already in your bank/cash records.';return;}
      if(mode==='unpaid'){status.textContent='The supplier bill will remain unpaid until you link a payment.';return;}
      let matches=[];try{if(value(form,'supplier')&&value(form,'amount'))matches=B.receiptMatches(p(),{supplier:value(form,'supplier'),accountId:value(form,'accountId'),date:value(form,'date'),categoryId:value(form,'categoryId'),amount:B.money(value(form,'amount'))});}catch{}
      if(matches.length===1)status.textContent=`Found one matching payment: ${matches[0].description} · ${pounds(-matches[0].amount)}. It will be linked without adding another expense.`;
      else if(matches.length>1){node('#receipt-match-field').hidden=false;select.innerHTML='<option value="">Leave unmatched for now</option>'+matches.map(t=>`<option value="${esc(t.id)}">${esc(t.description)} · ${pounds(-t.amount)}</option>`).join('');if(matches.some(t=>t.id===old))select.value=old;status.textContent=`${matches.length} payments match the supplier, date, and total. Choose one, or the receipt will be saved unpaid.`;}
      else status.textContent='Matches require the same supplier/merchant, date, and total. Without a match, the receipt is saved unpaid; no extra payment is created.';
    }
    function suggest(){const memory=B.findEntryMemory(p(),value(form,'accountId'),value(form,'supplier'),'payment');if(!manualCategory){if(memory&&(B.account(p(),memory.categoryId)?.type==='expense'||B.isSupplierAccount(p(),memory.categoryId))){category.set(memory.categoryId);if(!manualPercent)form.elements.businessPercent.value=memory.businessPercent;if(form.elements.vatCode)form.elements.vatCode.value=memory.vatCode||'out-of-scope';node('#entry-memory-status').textContent=`Remembered: ${categoryName(memory.categoryId)} · ${memory.businessPercent}% business use.`;}else{category.set(defaults('receipt').categoryId||d.categoryId||'fuel');if(!manualPercent)form.elements.businessPercent.value=defaults('receipt').businessPercent??100;if(form.elements.vatCode)form.elements.vatCode.value=defaults('receipt').vatCode||'out-of-scope';node('#entry-memory-status').textContent='Choose a category; this supplier and account will remember it when saved.';}}paymentPreview();}
    combo(form.elements.supplier,text=>p().contacts.filter(c=>c.type==='supplier'&&c.name.toLowerCase().startsWith(text.trim().toLowerCase())).map(c=>({label:c.name,detail:'Supplier'})),suggest,suggest);
    form.elements.categorySearch.addEventListener('input',()=>manualCategory=true);form.elements.categorySearch.addEventListener('categorychosen',()=>manualCategory=true);form.elements.businessPercent.addEventListener('input',()=>manualPercent=true);
    form.elements.accountId.addEventListener('change',()=>{manualCategory=false;manualPercent=false;suggest();});for(const name of ['amount','date','paymentMode']){form.elements[name].addEventListener('input',paymentPreview);form.elements[name].addEventListener('change',paymentPreview);}
    paymentPreview();focusEntry(form,'date');
  }
  function bulkCategory(ids,onSaved){let category;modal(`Categorise ${ids.length} transactions`,`<div class="form-grid"><input name="accountId" type="hidden" value="${esc(p().transactions.find(t=>ids.includes(t.id))?.accountId||'bank')}">${categoryField('fuel')}${selectField('VAT code','vatCode',vatOptions('out-of-scope'))}${field('Business use (%)','businessPercent','number',100,'required min="0" max="100" step="0.01"')}</div><div class="notice">Applies to every selected row, including other pages. Your choices are remembered separately for each account.</div>`,'Apply category',async(f,form)=>{category.sync();await change(()=>{const rows=p().transactions.filter(t=>ids.includes(t.id));if(rows.length!==ids.length||rows.some(t=>!B.canCategorise(p(),t)))throw new Error('Some selected entries cannot be categorised. Refresh your selection.');rows.forEach(t=>B.updateTransaction(p(),t.id,{categoryId:value(form,'categoryId'),vatCode:value(form,'vatCode')||'out-of-scope',businessPercent:Number(f.get('businessPercent'))}));onSaved();},`${ids.length} transactions categorised`);});category=wireCategory(node('#modal-form'));}
  function autoCategorise(rows){const plan=B.autoCategorisationPlan(p(),rows);
    if(!plan.matches.length){detailModal('No remembered matches yet',`<p>Categorise one Shell or BP payment on this account first, then try Auto categorise again.</p><p class="muted">Only uncategorised, unreconciled entries in open years are eligible. Ambiguous history is left for your review.</p>`);return;}
    modal('Apply remembered categories',`<p><strong>${plan.matches.length}</strong> transactions can be filled from this driver’s account memory. ${plan.unmatched.length} have no clear match.</p><div class="table-wrap"><table><thead><tr><th>Details / account</th><th>Suggested category</th><th>Business use</th></tr></thead><tbody>${plan.matches.slice(0,40).map(m=>`<tr><td class="details"><strong>${esc(m.description)}</strong><small>${esc(B.account(p(),m.accountId)?.name)}</small></td><td>${esc(categoryName(m.categoryId))}</td><td>${m.businessPercent}%</td></tr>`).join('')}</tbody></table></div><div class="notice">${plan.matches.length>40?'Showing the first 40 matches. All matching rows will be updated. ':''}Existing categories, invoice payments, transfers, reconciled entries, and locked years are preserved. Current filters apply.</div>`,'Apply categories',async()=>{await change(()=>B.applyAutoCategorisation(p(),plan),`${plan.matches.length} remembered categories applied`);});
  }
  return {transaction,receipt,bulkCategory,autoCategorise,categoryField,wireCategory};
}};
